// Registers the service worker generated by vite-plugin-pwa.
//
// `virtual:pwa-register` is the plugin's supported registration entry point
// (not a hand-rolled `navigator.serviceWorker.register(...)` call). It no-ops
// safely in dev/test — the virtual module only resolves when the PWA plugin
// runs, so this file has no effect outside a real Vite build.
//
// Update behaviour: the app uses `registerType: 'autoUpdate'` (see
// vite.config.js). The plugin handles the swap itself — the new worker calls
// skipWaiting + clientsClaim and the page reloads once the new worker is in
// control. There is deliberately nothing to click: the previous 'prompt'
// setup logged to the console and waited for a UI that was never built, so
// deploys never reached anyone, and a hash change left members staring at a
// broken crest.
//
// What this file still adds on top of the default is the periodic check
// below. Without it, an installed PWA that is never fully closed may not
// notice a deploy for a long time: the browser only re-checks the worker
// script on navigation, and a standalone PWA left open on a phone does not
// navigate. An hourly poll means a deploy lands within the hour instead of
// whenever the member happens to cold-start the app.
import { registerSW } from 'virtual:pwa-register'

// Hourly. Long enough to be invisible in bandwidth terms (it is a conditional
// request for one small script), short enough that a fix reaches the club the
// same afternoon.
//
// ⚠️ THE TIMER ALONE WAS NOT ENOUGH, AND JAY REPORTED THE SYMPTOM: "changes are
// immediately showing up on the desktop site but not the app". A browser tab
// re-checks the worker script on every page load, so the site looks instant. An
// INSTALLED PWA does not navigate — you switch away and back — so it waited up
// to an hour, and the moment somebody looks at it is exactly the moment it had
// not checked.
//
// Measured on production 14 Aug 2026 before changing anything, because the
// obvious suspects were both innocent: `sw.js` is served
// `public, must-revalidate, max-age=0` (so nothing stale is cached) and the
// deployed worker does contain skipWaiting and clientsClaim (so once fetched it
// takes over and reloads). The gap was only ever WHEN the check happens.
const UPDATE_CHECK_MS = 60 * 60 * 1000

// ⚠️ A FLOOR ON HOW OFTEN A CHECK CAN FIRE. Without it, switching between apps
// on a phone — which is a visibilitychange every time — would issue a request
// per flick. One a minute is far more responsive than the hour it replaces and
// still costs nothing.
const MIN_GAP_MS = 60 * 1000

// ⚠️ A PASSIVE LINE, NOT A PROMPT (2 Sep 2026 UX review, extra findings).
// registerType stays autoUpdate — the new worker still claims clients and the
// next navigation gets the new bundle, which is what the hourly check above
// exists for. What was missing is a word to the person mid-form: this fires
// `app-updated` on window when a worker REPLACES a controlling one, and
// AppShell shows "refresh when convenient". The first install (controller was
// null) is not an update and says nothing.
if (typeof navigator !== 'undefined' && navigator.serviceWorker) {
  const hadController = Boolean(navigator.serviceWorker.controller)
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (hadController) window.dispatchEvent(new CustomEvent('app-updated'))
  })
}

registerSW({
  // Runs once the worker is registered. `registration` is the live
  // ServiceWorkerRegistration; calling .update() on it asks the browser to
  // re-fetch the worker script and, if it changed, start the swap.
  onRegisteredSW(swUrl, registration) {
    if (!registration) return

    let lastCheck = 0

    // update() rejects when the worker script is unreachable, which is routine
    // on a flaky connection, so swallow it rather than surfacing an unhandled
    // rejection. A hidden or offline app is skipped — the next trigger picks it
    // up, and there are now three of them.
    const check = () => {
      if (document.visibilityState !== 'visible') return
      if (!navigator.onLine) return
      const now = Date.now()
      if (now - lastCheck < MIN_GAP_MS) return
      lastCheck = now
      registration.update().catch(() => {})
    }

    // ⚠️ THE ONE THAT ACTUALLY FIXES THE REPORT. Bringing the app back to the
    // foreground is the moment a member expects to see the latest, and for an
    // installed PWA it is the ONLY signal that resembles a page load.
    document.addEventListener('visibilitychange', check)

    // Coming back online after a spell without signal — pitch-side, in other
    // words — is the other moment a check is both cheap and likely to find
    // something.
    window.addEventListener('online', check)

    // Kept as the backstop for an app left open and visible for hours, which
    // neither listener above would ever fire for.
    setInterval(check, UPDATE_CHECK_MS)
  },

  onOfflineReady() {
    // eslint-disable-next-line no-console
    console.info('[Quins] App ready to work offline.')
  },
})
